package org.jsoup.select;

import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.junit.jupiter.api.Test;

public class ScratchHasTest {
    static void show(String html, String q) {
        Document doc = Jsoup.parse(html);
        Elements els = doc.select(q);
        StringBuilder sb = new StringBuilder();
        for (org.jsoup.nodes.Element el : els) sb.append(el.id()).append(' ');
        System.out.printf("%-40s -> [%s]%n", q, sb.toString().trim());
    }

    @Test public void probe() {
        String h1 = "<article id=a></article><p id=gap></p><!--c--><b></b><i></i>";
        show(h1, "article:has(~ ::comment)");        // expect a
        show(h1, "article:has(:scope ~ ::comment)"); // expect a
        show(h1, "article:has(+ ::comment)");        // expect empty
        show(h1, "article:has(:scope + ::comment)"); // expect empty

        String h2 = "<article id=a></article><!--c--><b></b>txt<i></i>";
        show(h2, "article:has(+ ::comment + b)");    // expect a
        show(h2, "article:has(+ b + i)");            // expect a
        show(h2, "article:has(+ ::comment + b + i)");// expect empty

        String h3 = "<article id=a></article><p id=gap></p>txt";
        show(h3, "article:has(~ ::text)");           // expect a
        show(h3, "article:has(+ ::text)");           // expect empty

        // chain-wide node mode: text between scope and comment should break the leading +
        String h4 = "<article id=a></article>txt<!--c--><b></b>";
        show(h4, "article:has(+ ::comment + b)");    // expect empty per chain-wide node semantics
        show(h4, "article:has(~ ::comment + b)");    // expect a
    }
}

